require_once __DIR__.'/../includes/bootstrap.php';if(current_user())redirect('../dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!rate_limit_key($email.'|'.client_ip()))$err='Too many attempts. Please retry shortly.';else{$q=db()->prepare('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if($u&&$u['status']==='active'&&password_verify($pass,$u['password_hash'])){login_user($u);db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);AuditService::log('LOGIN','auth',$u['id'],'Successful login');redirect('../dashboard.php');}$err='Invalid credentials or inactive account';}}?><!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>DCOS 2077 Login</title><link rel='stylesheet' href='../assets/css/app.css'></head><body class='login-bg'><div class='login-card'><div class='brand big'>DCOS <span>2077</span></div><h2>Digital College Operating System</h2><p>Secure, connected, role-based campus access.</p><?php if(!empty($err)):?><div class='alert alert-danger'><?=e($err)?></div><?php endif;?><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><label>Email</label><input class='form-control mb-3' name='email' type='email' required><label>Password</label><input class='form-control mb-3' name='password' type='password' required><button class='btn btn-primary w-100'>Enter Digital Campus</button></form><div class='demo-box mt-3'><strong>Demo accounts</strong><br>admin@college.com / Admin@123<br>faculty@college.com / Faculty@123<br>student@college.com / Student@123</div><a href='forgot.php' class='d-block mt-3'>Forgot password?</a></div></body></html>